snorkeling trash can; new whittling fire extinguisher
"""

OPTIONS = {
    "A": "circular large old-fashioned driving good black sofa",
    "B": "wood filipino ancient smoking awful violet tiny prismlike fork",
    "C": "prismlike brand-new smoking ridiculous violet iranian paper bed",
    "D": "old drinking terrible white normal-size square wrench",
    "E": "cloth thai brand-new eating good blue plate",
    "F": "fiberglass indonesian brand-new smoking wonderful cyan massive bottle",
    "G": "big rectangular archaic smoking terrible yellow vase",
    "H": "thai old drinking nice green massive pyramidal clock",
    "I": "glass bangladeshi old-fashioned snorkeling nice magenta prismlike canvas",
    "J": "spherical little ancient walking good indigo bangladeshi jar",
}

# Build precedence relation from the givens (unknown words are nouns and skipped).
entries = [e.strip() for e in GIVENS.replace("\n", " ").split(";") if e.strip()]
rel = set()
for e in entries:
    seq = [LEX[w] for w in e.split()[:-1] if w in LEX]
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            if seq[i] != seq[j]:
                rel.add((seq[i], seq[j]))

# Transitive closure.
changed = True
while changed:
    changed = False
    for (a, b) in list(rel):
        for (c, d) in list(rel):
            if b == c and (a, d) not in rel and a != d:
                rel.add((a, d))
                changed = True


def classify(phrase):
    mods = phrase.split()[:-1]
    if any(w not in LEX for w in mods):
        return "unsupported"
    seq = [LEX[w] for w in mods]
    undetermined = False
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            a, b = seq[i], seq[j]
            if a == b or (b, a) in rel:
                return "incorrect"
            if (a, b) not in rel:
                undetermined = True
    return "undetermined" if undetermined else "correct"


status = {k: classify(v) for k, v in OPTIONS.items()}
correct = [k for k in sorted(status) if status[k] == "correct"]
pending = [k for k in sorted(status) if status[k] in ("undetermined", "unsupported")]

if pending:
    final_answer = "UNSUPPORTED"
else:
    final_answer = "".join(correct) if correct else "K"

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "option_status": status,
        "confirmed_correct": correct,
        "unsettled": pending,
        "precedence_pairs": len(rel),
    },
}, sort_keys=True))
